import json
from pathlib import Path
for q in ['q2','q3']:
    meta_path=Path(f'/root/2025-{q}/FORM13F_metadata.json')
    meta=json.loads(meta_path.read_text())
    # try to locate 'VALUE' field description
    def find_value(obj, path=''):
        if isinstance(obj, dict):
            for k,v in obj.items():
                if k.lower()=='value' or (isinstance(v,str) and 'value' in v.lower() and 'thousand' in v.lower()):
                    pass
                find_value(v, path+'/'+k)
        elif isinstance(obj, list):
            for i,v in enumerate(obj):
                find_value(v, path+f'[{i}]')
    # print a few likely keys
    print('==',q,'metadata top keys==', list(meta.keys())[:20])
    for k in ['INFOTABLE','infotable','fields','schema','columns']:
        if k in meta:
            print('found',k)
    # heuristic: print any entries containing 'VALUE'
    txt=meta_path.read_text()
    if 'VALUE' in txt:
        idx=txt.index('VALUE')
        print('...context...', txt[max(0,idx-200):idx+300].replace('\n',' ') )
    else:
        print('VALUE not found as literal in metadata')
